style.css:
@-moz-document domain("www.google.com") {
/* 検索結果の順位をリセット */
  div#search div[data-hveid] {
    counter-reset: result-counter;
    position: relative;
    list-style: none;
  }

  /* 各検索結果に順位を付ける */
  div#search div[data-hveid] {
    counter-increment: result-counter;
    padding-left: 2em; /* 順位番号のスペースを確保 */
  }

  div#search div[data-hveid]::before {
    content: counter(result-counter) ". ";
    position: absolute;
    left: 0;
    color: #555; /* 順位番号の色を設定（任意） */
  }
}
